     1→//! Transaction abstractions for EVM execution.
     2→//!
     3→//! This module provides traits and implementations for converting various transaction formats
     4→//! into a unified transaction environment ([`TxEnv`]) that the EVM can execute. The main purpose
     5→//! of these traits is to enable flexible transaction input while maintaining type safety.
     6→
     7→use alloy_consensus::{
     8→    crypto::secp256k1, transaction::Recovered, EthereumTxEnvelope, TxEip1559, TxEip2930, TxEip4844,
     9→    TxEip7702, TxLegacy,
    10→};
    11→use alloy_eips::{
    12→    eip2718::WithEncoded,
    13→    eip7702::{RecoveredAuthority, RecoveredAuthorization},
    14→    Typed2718,
    15→};
    16→use alloy_primitives::{Address, Bytes, TxKind};
    17→use revm::{context::TxEnv, context_interface::either::Either};
    18→
    19→/// Trait marking types that can be converted into a transaction environment.
    20→///
    21→/// This is the primary trait that enables flexible transaction input for the EVM. The EVM's
    22→/// associated type `Evm::Tx` must implement this trait, and the `transact` method accepts
    23→/// any type implementing [`IntoTxEnv<Evm::Tx>`](IntoTxEnv).
    24→///
    25→/// # Example
    26→///
    27→/// ```ignore
    28→/// // Direct TxEnv usage
    29→/// let tx_env = TxEnv { caller: address, gas_limit: 100_000, ... };
    30→/// evm.transact(tx_env)?;
    31→///
    32→/// // Using a recovered transaction
    33→/// let recovered = tx.recover_signer()?;
    34→/// evm.transact(recovered)?;
    35→///
    36→/// // Using a transaction with encoded bytes
    37→/// let with_encoded = WithEncoded::new(recovered, encoded_bytes);
    38→/// evm.transact(with_encoded)?;
    39→/// ```
    40→pub trait IntoTxEnv<TxEnv> {
    41→    /// Converts `self` into [`TxEnv`].
    42→    fn into_tx_env(self) -> TxEnv;
    43→}
    44→
    45→impl IntoTxEnv<Self> for TxEnv {
    46→    fn into_tx_env(self) -> Self {
    47→        self
    48→    }
    49→}
    50→
    51→/// A helper trait to allow implementing [`IntoTxEnv`] for types that build transaction environment
    52→/// by cloning data.
    53→#[auto_impl::auto_impl(&)]
    54→pub trait ToTxEnv<TxEnv> {
    55→    /// Builds a [`TxEnv`] from `self`.
    56→    fn to_tx_env(&self) -> TxEnv;
    57→}
    58→
    59→impl<T, TxEnv> IntoTxEnv<TxEnv> for T
    60→where
    61→    T: ToTxEnv<TxEnv>,
    62→{
    63→    fn into_tx_env(self) -> TxEnv {
    64→        self.to_tx_env()
    65→    }
    66→}
    67→
    68→impl<L, R, TxEnv> ToTxEnv<TxEnv> for Either<L, R>
    69→where
    70→    L: ToTxEnv<TxEnv>,
    71→    R: ToTxEnv<TxEnv>,
    72→{
    73→    fn to_tx_env(&self) -> TxEnv {
    74→        match self {
    75→            Self::Left(l) => l.to_tx_env(),
    76→            Self::Right(r) => r.to_tx_env(),
    77→        }
    78→    }
    79→}
    80→
    81→#[cfg(feature = "op")]
    82→impl<T> IntoTxEnv<Self> for op_revm::OpTransaction<T>
    83→where
    84→    T: revm::context_interface::transaction::Transaction,
    85→{
    86→    fn into_tx_env(self) -> Self {
    87→        self
    88→    }
    89→}
    90→
    91→/// Helper trait for building a transaction environment from a recovered transaction.
    92→///
    93→/// This trait enables the conversion of consensus transaction types (which have been recovered
    94→/// with their sender address) into the EVM's transaction environment. It's automatically used
    95→/// when a [`Recovered<T>`] type is passed to the EVM's `transact` method.
    96→///
    97→/// The expectation is that any recovered consensus transaction can be converted into the
    98→/// transaction type that the EVM operates on (typically [`TxEnv`]).
    99→///
   100→/// # Implementation
   101→///
   102→/// This trait is implemented for all standard Ethereum transaction types ([`TxLegacy`],
   103→/// [`TxEip2930`], [`TxEip1559`], [`TxEip4844`], [`TxEip7702`]) and transaction envelopes
   104→/// ([`EthereumTxEnvelope`]).
   105→///
   106→/// # Example
   107→///
   108→/// ```ignore
   109→/// // Recover the signer from a transaction
   110→/// let recovered = tx.recover_signer()?;
   111→///
   112→/// // The recovered transaction can now be used with the EVM
   113→/// // This works because Recovered<T> implements IntoTxEnv when T implements FromRecoveredTx
   114→/// evm.transact(recovered)?;
   115→/// ```
   116→pub trait FromRecoveredTx<Tx> {
   117→    /// Builds a [`TxEnv`] from a transaction and a sender address.
   118→    fn from_recovered_tx(tx: &Tx, sender: Address) -> Self;
   119→}
   120→
   121→impl<TxEnv, T> FromRecoveredTx<&T> for TxEnv
   122→where
   123→    TxEnv: FromRecoveredTx<T>,
   124→{
   125→    fn from_recovered_tx(tx: &&T, sender: Address) -> Self {
   126→        TxEnv::from_recovered_tx(tx, sender)
   127→    }
   128→}
   129→
   130→impl<T, TxEnv: FromRecoveredTx<T>> ToTxEnv<TxEnv> for Recovered<T> {
   131→    fn to_tx_env(&self) -> TxEnv {
   132→        TxEnv::from_recovered_tx(self.inner(), self.signer())
   133→    }
   134→}
   135→
   136→impl FromRecoveredTx<TxLegacy> for TxEnv {
   137→    fn from_recovered_tx(tx: &TxLegacy, caller: Address) -> Self {
   138→        let TxLegacy { chain_id, nonce, gas_price, gas_limit, to, value, input } = tx;
   139→        Self {
   140→            tx_type: tx.ty(),
   141→            caller,
   142→            gas_limit: *gas_limit,
   143→            gas_price: *gas_price,
   144→            kind: *to,
   145→            value: *value,
   146→            data: input.clone(),
   147→            nonce: *nonce,
   148→            chain_id: *chain_id,
   149→            ..Default::default()
   150→        }
   151→    }
   152→}
   153→
   154→impl FromTxWithEncoded<TxLegacy> for TxEnv {
   155→    fn from_encoded_tx(tx: &TxLegacy, sender: Address, _encoded: Bytes) -> Self {
   156→        Self::from_recovered_tx(tx, sender)
   157→    }
   158→}
   159→
   160→impl FromRecoveredTx<TxEip2930> for TxEnv {
   161→    fn from_recovered_tx(tx: &TxEip2930, caller: Address) -> Self {
   162→        let TxEip2930 { chain_id, nonce, gas_price, gas_limit, to, value, access_list, input } = tx;
   163→        Self {
   164→            tx_type: tx.ty(),
   165→            caller,
   166→            gas_limit: *gas_limit,
   167→            gas_price: *gas_price,
   168→            kind: *to,
   169→            value: *value,
   170→            data: input.clone(),
   171→            chain_id: Some(*chain_id),
   172→            nonce: *nonce,
   173→            access_list: access_list.clone(),
   174→            ..Default::default()
   175→        }
   176→    }
   177→}
   178→
   179→impl FromTxWithEncoded<TxEip2930> for TxEnv {
   180→    fn from_encoded_tx(tx: &TxEip2930, sender: Address, _encoded: Bytes) -> Self {
   181→        Self::from_recovered_tx(tx, sender)
   182→    }
   183→}
   184→
   185→impl FromRecoveredTx<TxEip1559> for TxEnv {
   186→    fn from_recovered_tx(tx: &TxEip1559, caller: Address) -> Self {
   187→        let TxEip1559 {
   188→            chain_id,
   189→            nonce,
   190→            gas_limit,
   191→            to,
   192→            value,
   193→            input,
   194→            max_fee_per_gas,
   195→            max_priority_fee_per_gas,
   196→            access_list,
   197→        } = tx;
   198→        Self {
   199→            tx_type: tx.ty(),
   200→            caller,
   201→            gas_limit: *gas_limit,
   202→            gas_price: *max_fee_per_gas,
   203→            kind: *to,
   204→            value: *value,
   205→            data: input.clone(),
   206→            nonce: *nonce,
   207→            chain_id: Some(*chain_id),
   208→            gas_priority_fee: Some(*max_priority_fee_per_gas),
   209→            access_list: access_list.clone(),
   210→            ..Default::default()
   211→        }
   212→    }
   213→}
   214→
   215→impl FromTxWithEncoded<TxEip1559> for TxEnv {
   216→    fn from_encoded_tx(tx: &TxEip1559, sender: Address, _encoded: Bytes) -> Self {
   217→        Self::from_recovered_tx(tx, sender)
   218→    }
   219→}
   220→
   221→impl FromRecoveredTx<TxEip4844> for TxEnv {
   222→    fn from_recovered_tx(tx: &TxEip4844, caller: Address) -> Self {
   223→        let TxEip4844 {
   224→            chain_id,
   225→            nonce,
   226→            gas_limit,
   227→            to,
   228→            value,
   229→            input,
   230→            max_fee_per_gas,
   231→            max_priority_fee_per_gas,
   232→            access_list,
   233→            blob_versioned_hashes,
   234→            max_fee_per_blob_gas,
   235→        } = tx;
   236→        Self {
   237→            tx_type: tx.ty(),
   238→            caller,
   239→            gas_limit: *gas_limit,
   240→            gas_price: *max_fee_per_gas,
   241→            kind: TxKind::Call(*to),
   242→            value: *value,
   243→            data: input.clone(),
   244→            nonce: *nonce,
   245→            chain_id: Some(*chain_id),
   246→            gas_priority_fee: Some(*max_priority_fee_per_gas),
   247→            access_list: access_list.clone(),
   248→            blob_hashes: blob_versioned_hashes.clone(),
   249→            max_fee_per_blob_gas: *max_fee_per_blob_gas,
