   374→/// Helper trait for building a transaction environment from a transaction with its encoded form.
   375→///
   376→/// This trait enables the conversion of consensus transaction types along with their EIP-2718
   377→/// encoded bytes into the EVM's transaction environment. It's automatically used when a
   378→/// [`WithEncoded<Recovered<T>>`](WithEncoded) type is passed to the EVM's `transact` method.
   379→///
   380→/// The main purpose of this trait is to allow preserving the original encoded transaction data
   381→/// alongside the parsed transaction, which can be useful for:
   382→/// - Signature verification
   383→/// - Transaction hash computation
   384→/// - Re-encoding for network propagation
   385→/// - Optimism transaction handling (which requires encoded data, for Data availability costs).
   386→///
   387→/// # Implementation
   388→///
   389→/// Most implementations simply delegate to [`FromRecoveredTx`], ignoring the encoded bytes.
   390→/// However, specialized implementations (like Optimism's `OpTransaction`) may use the encoded
   391→/// data for additional functionality.
   392→///
   393→/// # Example
   394→///
   395→/// ```ignore
   396→/// // Create a transaction with its encoded form
   397→/// let encoded_bytes = tx.encoded_2718();
   398→/// let recovered = tx.recover_signer()?;
   399→/// let with_encoded = WithEncoded::new(recovered, encoded_bytes);
   400→///
   401→/// // The transaction with encoded data can be used with the EVM
   402→/// evm.transact(with_encoded)?;
   403→/// ```
   404→pub trait FromTxWithEncoded<Tx> {
   405→    /// Builds a [`TxEnv`] from a transaction, its sender, and encoded transaction bytes.
   406→    fn from_encoded_tx(tx: &Tx, sender: Address, encoded: Bytes) -> Self;
   407→}
   408→
   409→impl<TxEnv, T> FromTxWithEncoded<&T> for TxEnv
   410→where
   411→    TxEnv: FromTxWithEncoded<T>,
   412→{
   413→    fn from_encoded_tx(tx: &&T, sender: Address, encoded: Bytes) -> Self {
   414→        TxEnv::from_encoded_tx(tx, sender, encoded)
   415→    }
   416→}
   417→
   418→impl<T, TxEnv: FromTxWithEncoded<T>> ToTxEnv<TxEnv> for WithEncoded<Recovered<T>> {
   419→    fn to_tx_env(&self) -> TxEnv {
   420→        let recovered = &self.1;
   421→        TxEnv::from_encoded_tx(recovered.inner(), recovered.signer(), self.encoded_bytes().clone())
   422→    }
   423→}
   424→
   425→impl<T, TxEnv: FromTxWithEncoded<T>> ToTxEnv<TxEnv> for WithEncoded<&Recovered<T>> {
   426→    fn to_tx_env(&self) -> TxEnv {
   427→        TxEnv::from_encoded_tx(self.value(), *self.value().signer(), self.encoded_bytes().clone())
   428→    }
   429→}
   430→
   431→impl<Eip4844: AsRef<TxEip4844>> FromTxWithEncoded<EthereumTxEnvelope<Eip4844>> for TxEnv {
   432→    fn from_encoded_tx(tx: &EthereumTxEnvelope<Eip4844>, caller: Address, encoded: Bytes) -> Self {
   433→        match tx {
   434→            EthereumTxEnvelope::Legacy(tx) => Self::from_encoded_tx(tx.tx(), caller, encoded),
   435→            EthereumTxEnvelope::Eip1559(tx) => Self::from_encoded_tx(tx.tx(), caller, encoded),
   436→            EthereumTxEnvelope::Eip2930(tx) => Self::from_encoded_tx(tx.tx(), caller, encoded),
   437→            EthereumTxEnvelope::Eip4844(tx) => {
   438→                Self::from_encoded_tx(tx.tx().as_ref(), caller, encoded)
   439→            }
   440→            EthereumTxEnvelope::Eip7702(tx) => Self::from_encoded_tx(tx.tx(), caller, encoded),
   441→        }
   442→    }
   443→}
   444→
   445→impl<Eip4844: AsRef<TxEip4844>> FromRecoveredTx<EthereumTxEnvelope<Eip4844>> for TxEnv {
   446→    fn from_recovered_tx(tx: &EthereumTxEnvelope<Eip4844>, sender: Address) -> Self {
   447→        match tx {
   448→            EthereumTxEnvelope::Legacy(tx) => Self::from_recovered_tx(tx.tx(), sender),
   449→            EthereumTxEnvelope::Eip1559(tx) => Self::from_recovered_tx(tx.tx(), sender),
   450→            EthereumTxEnvelope::Eip2930(tx) => Self::from_recovered_tx(tx.tx(), sender),
   451→            EthereumTxEnvelope::Eip4844(tx) => Self::from_recovered_tx(tx.tx().as_ref(), sender),
   452→            EthereumTxEnvelope::Eip7702(tx) => Self::from_recovered_tx(tx.tx(), sender),
   453→        }
   454→    }
   455→}
   456→
   457→#[cfg(test)]
   458→mod tests {
   459→    use super::*;
   460→
   461→    struct MyTxEnv;
   462→    struct MyTransaction;
   463→
   464→    impl IntoTxEnv<Self> for MyTxEnv {
   465→        fn into_tx_env(self) -> Self {
   466→            self
   467→        }
   468→    }
   469→
   470→    impl FromRecoveredTx<MyTransaction> for MyTxEnv {
   471→        fn from_recovered_tx(_tx: &MyTransaction, _sender: Address) -> Self {
   472→            Self
   473→        }
   474→    }
   475→
   476→    impl FromTxWithEncoded<MyTransaction> for MyTxEnv {
   477→        fn from_encoded_tx(_tx: &MyTransaction, _sender: Address, _encoded: Bytes) -> Self {
   478→            Self
   479→        }
   480→    }
   481→
   482→    const fn assert_env<T: IntoTxEnv<MyTxEnv>>() {}
   483→    const fn assert_recoverable<T: RecoveredTx<MyTransaction>>() {}
   484→
   485→    #[test]
   486→    const fn test_into_tx_env() {
   487→        assert_env::<MyTxEnv>();
   488→        assert_env::<&Recovered<MyTransaction>>();
   489→        assert_env::<&Recovered<&MyTransaction>>();
   490→    }
   491→
   492→    #[test]
   493→    const fn test_into_encoded_tx_env() {
   494→        assert_env::<WithEncoded<Recovered<MyTransaction>>>();
   495→        assert_env::<&WithEncoded<Recovered<MyTransaction>>>();
   496→
   497→        assert_recoverable::<Recovered<MyTransaction>>();
   498→        assert_recoverable::<WithEncoded<Recovered<MyTransaction>>>();
   499→    }
   500→}
